<?php
namespace App\Services; use App\Models\Order;
class PayFastService { public function redirectData(Order $order):array { $data=['merchant_id'=>config('payfast.merchant_id'),'merchant_key'=>config('payfast.merchant_key'),'return_url'=>route('payment.return',['order'=>$order->number]),'cancel_url'=>route('payment.cancel',['order'=>$order->number]),'notify_url'=>route('payment.notify'),'name_first'=>$order->customer->name,'email_address'=>$order->customer->email,'m_payment_id'=>$order->number,'amount'=>number_format($order->grand_total,2,'.',''),'item_name'=>'Mks Eats order '.$order->number]; if($passphrase=config('payfast.passphrase')){$data['signature']=$this->signature($data,$passphrase);} return $data; } public function signature(array $data,string $passphrase):string {ksort($data);return md5(http_build_query($data).'&passphrase='.urlencode($passphrase));} }
